import {escapeHtml as esc} from './agent-view.js';
const labels={baseline:'基準 Skill・凍結後沿用',proposal:'模型 Skill 提案',selection:'最後選定 Skill',pending:'尚未完成選擇'};
const notes={'Frozen baseline Skill':'本輪固定基準。','Fixed Skill throughout this repair; no Skill proposal or activation':'此 Python 修復全程使用固定 Skill，沒有執行 Skill 演化。','Matches selected Skill':'本文符合最後選定 Skill；啟用仍需通過評測與核准。','Not selected':'最後未選用；提案不等於演化成果。','Selection not completed':'已記錄提案，尚未完成選擇。','Selection frozen; release requires completed independent review and approval':'已凍結選擇；評估、審查與人工核准分別確認。','No frozen selection; no evolution outcome confirmed':'尚無凍結的選擇，無法確認演化成果。'};
const tools={read_solution:'讀取程式',write_solution:'寫入程式',run_tests:'執行公開測試'},statuses={completed:'已完成',failed:'失敗',running:'執行中'},stages={search:'搜尋',baseline:'基準最後評測',selected:'選定 Skill 最後評測'};
const code=s=>`<pre>${esc(s??'沒有保存此份原始碼')}</pre>`;
const splits={train:'訓練',validation:'驗證',heldout:'最終保留'},difficulties={easy:'初階',medium:'中階',hard:'進階'};
const testCount=m=>m?`${m.passed}/${m.total}`:'未保存';
function attemptTable(data,busy){
 const catalog=data.taskCatalog;
 return `<h3>逐題修復與 Skill 對照紀錄</h3><p class="body-copy">共 ${data.totalRollouts} 次 · 本頁 ${data.totalRollouts?data.offset+1:0}–${Math.min(data.offset+data.rollouts.length,data.totalRollouts)}。同題次數依本 Run 全部 rollout 排序，跨階段累計；每次皆從錯誤起始程式重新修復。寫入次數另計，含遭拒與相同程式。點選 rollout 查看實際程式與完整 Skill。</p>
 <p class="small-notice">測試數取自已保存的獨立評測：公開／保留案例各自列出，沒有紀錄即標示未保存。程式修復成功與 Skill 改善分別判定；整輪審查狀態見上方成果。</p>
 <div class="table-wrap"><table><thead><tr><th>Rollout／同題第幾次</th><th>題目／難度／面向</th><th>分割／評測階段</th><th>起始程式測試</th><th>修復後測試</th><th>該次結果</th><th>使用 Skill／識別碼</th><th>程式寫入嘗試</th></tr></thead><tbody>${data.rollouts.map(r=>{
 const e=r.records?.evaluation,w=r.records?.writes,skill=r.records?.skill,q=r.question;
 return `<tr><td><button class="text-button" data-change-rollout="${esc(r.id)}" data-change-run="${esc(data.runId)}" data-change-offset="${data.offset}">${esc(r.id)}${r.id===data.selectedRollout?' ✓':''}</button><br>同題第 ${r.attempt??'未知'} 次</td>
 <td>${esc(q?.title||r.taskId||'題目未知')}<br><code>${esc(r.taskId)}</code><br>${esc(difficulties[q?.difficulty]||'難度未保存')} · ${esc(q?.topic||'面向未保存')}</td><td>${esc(splits[q?.split]||'分割未保存')}<br>${esc(stages[r.stage]||r.stage||'未完成')}</td>
 <td>公開 ${testCount(e?.baseline.visible)}<br>保留 ${testCount(e?.baseline.hidden)}</td><td>公開 ${testCount(e?.candidate.visible)}<br>保留 ${testCount(e?.candidate.hidden)}</td>
 <td>${!r.completed?'未完成／中斷；無最終分數':!e?'已保存分數 '+(r.score??'未知')+'；測試明細未保存':e?.taskOutcome==='call-limit'?'單題額度耗盡・記為失敗':r.score===1?'可信任務測試通過':r.score===0?'可信任務測試未通過':'未保存最終分數'}${e?`<br>模型呼叫 ${e.calls??'未保存'} 次${e.sdkStopReason?` · ${esc(e.sdkStopReason)}`:''}`:''}</td>
 <td>${r.skillChanged===null?'未保存':r.skillChanged?'採用變更的 Skill':'沿用基準・未修改'}<br>${esc(skill?.label||'版本未保存')} · ${esc(skill?.name||'名稱未保存')}<br><code title="${esc(skill?.hash||'')}">${esc(skill?.hash?.slice(0,12)||'hash 未保存')}</code></td>
 <td>${w?`要求 ${w.attempted} 次／套用 ${w.applied} 次<br>有變更 ${w.changed??'未知'} 次／遭拒 ${w.rejected} 次`:'未保存寫入紀錄'}</td></tr>`;
 }).join('')||'<tr><td colspan="8">尚無修復紀錄</td></tr>'}</tbody></table></div>
 <div class="actions card-actions"><button class="button secondary" data-change-page="${Math.max(0,data.offset-data.limit)}" data-change-run="${esc(data.runId)}" ${data.offset===0||busy?'disabled':''}>上一頁</button><button class="button secondary" data-change-page="${data.offset+data.limit}" data-change-run="${esc(data.runId)}" ${data.offset+data.limit>=data.totalRollouts||busy?'disabled':''}>下一頁</button></div>
 ${catalog?.tasks.length?`<details><summary>本 Run 凍結題庫覆蓋 · v${esc(catalog.revision)} · ${catalog.tasks.filter(q=>q.attempts>0).length}/${catalog.tasks.length} 題有嘗試</summary><p class="body-copy">訓練題依搜尋抽樣，收錄不表示已執行。此表依本 Run 凍結版本，不隨題庫編輯改變。${catalog.unassignedRollouts?'部分 rollout 題目未知，次數可能不完整。':''}</p><div class="table-wrap"><table><thead><tr><th>題目</th><th>分割／難度／面向</th><th>嘗試次數</th></tr></thead><tbody>${catalog.tasks.map(q=>`<tr><td>${esc(q.title)}<br><code>${esc(q.id)}</code></td><td>${esc(splits[q.split])}／${esc(difficulties[q.difficulty])}／${esc(q.topic)}</td><td>${q.attempts?`${q.attempts} 次`:catalog.unassignedRollouts?'無已知對應・部分紀錄不完整':'未執行・沒有測量結果'}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="body-copy">此 Run 沒有保存題庫目錄；只顯示實際 rollout，無法推定未測題目。</p>'}`;
}
export function changesView(runtime,run){
 const data=runtime.changes?.runId===run?.id?runtime.changes:null;
 const revision=runtime.changeRevision??0,busy=runtime.changeBusy;
 return `<section class="card spaced change-history" data-change-panel data-change-run-id="${esc(run?.id||'')}" data-change-revision="${revision}"><div class="card-heading"><div><h2>${run?.task==='gepa-evolution'?'逐題修復與 Skill 紀錄':'實際程式修改與 Skill 歷程'}</h2><p>讀取已保存的紀錄；失敗或執行中的嘗試也可檢閱。此操作不呼叫模型。展開明細時保留目前快照；收合或按更新後顯示新紀錄。</p></div><button class="button secondary" data-change-load="${esc(run?.id||'')}" ${!run||busy?'disabled':''}>${busy?'讀取中…':data?'更新歷程':'顯示實際修改歷程'}</button></div>
 ${runtime.changeError?`<p class="error-banner">${esc(runtime.changeError)}</p>`:''}
 ${data?`<div class="change-content"><p class="body-copy"><code>${esc(data.runId)}</code> · ${data.verified?'原 Run 記錄已完成審查・此處僅檢閱':'歷程快照・不代表整輪通過'}<br>每次未修改也會保留；測試當下通過不等於最終結果。</p>
 ${data.warnings.map(w=>`<p class="small-notice">部分紀錄無法預覽：${esc(w)}</p>`).join('')}
 ${data.task==='gepa-evolution'?attemptTable(data,busy):''}
 ${data.trace?`<h3>${esc(data.selectedRollout||'本輪 Python 修復')} · ${esc(data.trace.taskId)} · 程式歷程</h3>${data.trace.taskPrompt?`<details><summary>本題要求（凍結的任務說明）</summary>${code(data.trace.taskPrompt)}</details>`:''}<details><summary>起始錯誤程式</summary>${code(data.trace.baseline)}</details>
 ${data.trace.steps.map(s=>`<details class="source-step"><summary>#${esc(s.id)} ${esc(tools[s.name])} (${esc(s.name)}) · ${esc(statuses[s.status]||s.status)} · ${s.applied?(s.changed?'已套用程式修改':'寫入相同程式・未改變'):s.name==='write_solution'?'未套用這次寫入':'程式未修改'}${s.visibleTotal!==undefined?` · 公開測試 ${esc(s.visiblePassed)}/${esc(s.visibleTotal)}`:''}</summary>${s.error?`<p class="error-banner">${esc(s.error)}</p>`:''}${s.applied?`<div class="diff"><div><h4>修改前</h4>${code(s.before)}</div><div><h4>修改後</h4>${code(s.after)}</div></div><h4>實際 diff</h4>${code(s.patch||'無程式差異')}`:s.attemptedSource?`<h4>要求寫入的程式（未確認套用）</h4>${code(s.attemptedSource)}`:code(s.after)}</details>`).join('')||'<p class="body-copy">尚無已保存的工具步驟。</p>'}
 <details><summary>目前最後一次成功寫入的程式</summary>${code(data.trace.currentSource)}<p class="body-copy">${data.trace.candidate===null?'尚無凍結的 candidate；不要當成已通過修復。':data.trace.candidateMatchesTrace?'凍結 candidate 與寫入歷程一致；成效仍以獨立審查為準。':'凍結 candidate 與歷程不一致，請檢查證據。'}</p></details>
 <details><summary>這次嘗試實際使用的 Skill（固定）</summary>${code(data.trace.skill.body)}</details>`:'<p class="body-copy">尚無 rollout 程式紀錄。</p>'}
 <h3>Skill 每次提案與選擇</h3><p class="body-copy">${data.task==='gepa-evolution'?`已保存的模型提案 ${data.skillHistory.filter(s=>s.kind==='proposal').length} 次。搜尋可多次沿用同一 Skill；沒有提案時不補造修改紀錄。`:'此頁只修復 Python 程式；要修改 Skill 請使用 GEPA。'}</p>
 ${data.skillHistory.map(s=>`<details class="skill-step"><summary>${esc(s.id)} · ${esc(labels[s.kind]||s.kind)} · ${s.changed?'本文有修改':s.after===null?'尚無結果':'本文未修改'}${typeof s.validationScore==='number'?` · 搜尋驗證 ${Math.round(s.validationScore*100)}%`:''}</summary><p class="body-copy">${esc(notes[s.note]||s.note)}</p>${s.changed?`<div class="diff"><div><h4>修正前 Skill</h4>${code(s.before)}</div><div><h4>修正後 Skill</h4>${code(s.after)}</div></div><h4>Skill diff</h4>${code(s.patch)}`:code(s.after??s.before)}</details>`).join('')}</div>`:'<div class="empty">選擇 Run 後按「顯示實際修改歷程」。不必重新執行實驗。</div>'}</section>`;
}
